using VisualRelay.Core.Execution;
using VisualRelay.Domain;

namespace VisualRelay.Tests;

public sealed class SetupCheckResultsTests
{
    private static RelayConfig SampleConfig(string? guardCmd = null) =>
        new(
            TasksDir: "llm-tasks",
            TestCommand: "dotnet test",
            TestFileCommand: "",
            LogSources: [],
            TierProfiles: new Dictionary<string, string>(),
            EnableFixVerify: false,
            MaxStageFailures: 3,
            MaxTurns: 10,
            BaselineVerify: true,
            ArchiveOnDone: true,
            SubagentTimeoutMilliseconds: 300_000,
            TestTimeoutMilliseconds: 30_000,
            FirstOutputTimeoutMsByTier: new Dictionary<string, int>(),
            FirstOutputTimeoutMs: 90_000)
        {
            GuardCommand = guardCmd
        };

    private sealed record Stage10PreAgentData(
        TestRunResult TestResult, double TestDurationSeconds,
        bool BootstrapFailed, string? BootstrapFailureOutput, string? BootstrapCmd,
        string? NewGuardOutput, bool GuardFailed, string? GuardOutput);

    private static TestRunResult GreenResult() => new(0, "Tests passed!\n");
    private static TestRunResult RedResult() => new(1, "FAIL: SomeTest\n");

    [Fact]
    public void FromPreAgentData_AllGreen()
    {
        var data = new Stage10PreAgentData(
            GreenResult(), 1.5,
            BootstrapFailed: false, BootstrapFailureOutput: null, BootstrapCmd: "nix develop --command true",
            NewGuardOutput: null, GuardFailed: false, GuardOutput: null);
        var config = SampleConfig(guardCmd: "dotnet format --verify-no-changes");

        var results = RelayDriver.SetupCheckResults.FromPreAgentData(data, config);

        Assert.Equal("green", results.BootstrapCheck);
        Assert.Equal("nix develop --command true", results.BootstrapCommand);
        Assert.Null(results.BootstrapOutput);
        Assert.Equal("green", results.GuardCheck);
        Assert.Null(results.GuardOutput);
        Assert.Null(results.NewGuardProbeCheck);
        Assert.Null(results.NewGuardProbeOutput);
        Assert.Equal("green", results.TestCheck);
        Assert.Equal("dotnet test", results.TestCommand);
        Assert.Equal(0, results.TestExitCode);
    }

    [Fact]
    public void FromPreAgentData_BootstrapFailed()
    {
        var data = new Stage10PreAgentData(
            GreenResult(), 2.0,
            BootstrapFailed: true, BootstrapFailureOutput: "nix build failed", BootstrapCmd: "nix develop --command true",
            NewGuardOutput: null, GuardFailed: false, GuardOutput: null);
        var config = SampleConfig();

        var results = RelayDriver.SetupCheckResults.FromPreAgentData(data, config);

        Assert.Equal("red", results.BootstrapCheck);
        Assert.Equal("nix build failed", results.BootstrapOutput);
        Assert.Equal("green", results.TestCheck);
    }

    [Fact]
    public void FromPreAgentData_GuardFailed()
    {
        var data = new Stage10PreAgentData(
            GreenResult(), 3.0,
            BootstrapFailed: false, BootstrapFailureOutput: null, BootstrapCmd: "nix develop --command true",
            NewGuardOutput: null, GuardFailed: true, GuardOutput: "file too large");
        var config = SampleConfig(guardCmd: "dotnet format --verify-no-changes");

        var results = RelayDriver.SetupCheckResults.FromPreAgentData(data, config);

        Assert.Equal("green", results.BootstrapCheck);
        Assert.Equal("red", results.GuardCheck);
        Assert.Equal("file too large", results.GuardOutput);
        Assert.Equal("green", results.TestCheck);
    }

    [Fact]
    public void FromPreAgentData_BootstrapAndGuardSkipped()
    {
        var data = new Stage10PreAgentData(
            GreenResult(), 0.5,
            BootstrapFailed: false, BootstrapFailureOutput: null, BootstrapCmd: null,
            NewGuardOutput: null, GuardFailed: false, GuardOutput: null);
        var config = SampleConfig(guardCmd: null);

        var results = RelayDriver.SetupCheckResults.FromPreAgentData(data, config);

        Assert.Null(results.BootstrapCheck);
        Assert.Null(results.GuardCheck);
        Assert.Equal("green", results.TestCheck);
    }

    [Fact]
    public void FromFixVerifyIteration_BootstrapRed()
    {
        var bootstrapResult = new TestRunResult(1, "bootstrap error");
        var testResult = GreenResult();

        var results = RelayDriver.SetupCheckResults.FromFixVerifyIteration(
            bootstrapResult, "nix develop --command true", null, "dotnet format --verify-no-changes",
            testResult, "dotnet test");

        Assert.Equal("red", results.BootstrapCheck);
        Assert.Equal("bootstrap error", results.BootstrapOutput);
        Assert.Equal("green", results.GuardCheck);
        Assert.Null(results.GuardOutput);
        Assert.Null(results.NewGuardProbeCheck);
        Assert.Equal("green", results.TestCheck);
    }

    [Fact]
    public void ToEventData_OmitsNullChecks()
    {
        var data = new Stage10PreAgentData(
            GreenResult(), 0.1,
            BootstrapFailed: false, BootstrapFailureOutput: null, BootstrapCmd: null,
            NewGuardOutput: null, GuardFailed: false, GuardOutput: null);
        var config = SampleConfig(guardCmd: null);
        var results = RelayDriver.SetupCheckResults.FromPreAgentData(data, config);

        var eventData = results.ToEventData();

        Assert.False(eventData.ContainsKey("bootstrapCheck"));
        Assert.False(eventData.ContainsKey("guardCheck"));
        Assert.False(eventData.ContainsKey("newGuardProbeCheck"));
        Assert.Equal("green", eventData["testCheck"]);
        Assert.Equal("0", eventData["testExitCode"]);
    }

    [Fact]
    public void ToSummaryLines_FormatsCorrectly()
    {
        var data = new Stage10PreAgentData(
            RedResult(), 4.0,
            BootstrapFailed: true, BootstrapFailureOutput: "bootstrap down", BootstrapCmd: "nix develop --command true",
            NewGuardOutput: null, GuardFailed: true, GuardOutput: "violation");
        var config = SampleConfig(guardCmd: "dotnet format --verify-no-changes");
        var results = RelayDriver.SetupCheckResults.FromPreAgentData(data, config);

        var summary = results.ToSummaryLines();

        Assert.Contains("bootstrap", summary, StringComparison.OrdinalIgnoreCase);
        Assert.Contains("guard", summary, StringComparison.OrdinalIgnoreCase);
        Assert.Contains("test", summary, StringComparison.OrdinalIgnoreCase);
        Assert.Contains("✗", summary, StringComparison.Ordinal);
    }

    [Fact]
    public void IsAnyRed_TrueWhenBootstrapOrGuardRed()
    {
        var greenData = new Stage10PreAgentData(
            GreenResult(), 1.0,
            BootstrapFailed: false, BootstrapFailureOutput: null, BootstrapCmd: "nix develop --command true",
            NewGuardOutput: null, GuardFailed: false, GuardOutput: null);
        var config = SampleConfig(guardCmd: "dotnet format --verify-no-changes");
        var green = RelayDriver.SetupCheckResults.FromPreAgentData(greenData, config);
        Assert.False(green.IsAnyRed());

        var bootstrapRedData = new Stage10PreAgentData(
            GreenResult(), 1.0,
            BootstrapFailed: true, BootstrapFailureOutput: "err", BootstrapCmd: "nix develop --command true",
            NewGuardOutput: null, GuardFailed: false, GuardOutput: null);
        var bootstrapRed = RelayDriver.SetupCheckResults.FromPreAgentData(bootstrapRedData, config);
        Assert.True(bootstrapRed.IsAnyRed());

        var guardRedData = new Stage10PreAgentData(
            GreenResult(), 1.0,
            BootstrapFailed: false, BootstrapFailureOutput: null, BootstrapCmd: "nix develop --command true",
            NewGuardOutput: null, GuardFailed: true, GuardOutput: "err");
        var guardRed = RelayDriver.SetupCheckResults.FromPreAgentData(guardRedData, config);
        Assert.True(guardRed.IsAnyRed());
    }
}

