namespace VisualRelay.Domain;

/// <summary>
/// Surface-level snapshot of the most recent setup-check failure. Exposed
/// through the control API /state endpoint and the UI so every failure is
/// diagnosable without reading artifacts on disk. Null when the last setup
/// check passed (or hasn't run yet).
/// </summary>
public sealed record SetupCheckSurface(
    string? Command,
    string? Cwd,
    int TimeoutMs,
    int? ExitCode,
    bool TimedOut,
    string? OutputTail,
    string? ArtifactPath,
    DateTimeOffset? CapturedUtc)
{
    public static SetupCheckSurface? FromEventData(IReadOnlyDictionary<string, string>? data)
    {
        if (data is null) return null;
        if (!data.TryGetValue("setupCheck", out var check) || check != "red") return null;

        data.TryGetValue("setupCheckCommand", out var command);
        data.TryGetValue("setupCheckCwd", out var cwd);
        data.TryGetValue("setupCheckExitCode", out var exitCodeStr);
        data.TryGetValue("setupCheckTimedOut", out var timedOutStr);
        data.TryGetValue("setupCheckOutputTail", out var outputTail);
        data.TryGetValue("setupCheckArtifactPath", out var artifactPath);

        int.TryParse(data.GetValueOrDefault("setupCheckTimeoutMs", ""), out var timeoutMs);
        int? exitCode = int.TryParse(exitCodeStr, out var ec) ? ec : null;
        var timedOut = string.Equals(timedOutStr, "true", StringComparison.OrdinalIgnoreCase);

        return new SetupCheckSurface(
            Command: command,
            Cwd: cwd,
            TimeoutMs: timeoutMs,
            ExitCode: exitCode,
            TimedOut: timedOut,
            OutputTail: outputTail,
            ArtifactPath: artifactPath,
            CapturedUtc: DateTimeOffset.UtcNow);
    }
}

